/// </summary>
/// <param name = "_stepCurrent">NDXStepCurrent</param>
/// <param name = "_stepMax">NDXStepMax</param>
/// <returns>NDXHistoryLogProdIdentMaintainContract</returns>
static NDXHistoryLogProdIdentMaintainContract construct(NDXStepCurrent _stepCurrent, NDXStepMax _stepMax = 3)
{
    NDXHistoryLogProdIdentMaintainContract nDXHistoryLogProdIdentMaintainContract;
    nDXHistoryLogProdIdentMaintainContract = new NDXHistoryLogProdIdentMaintainContract();
    nDXHistoryLogProdIdentMaintainContract.stepCurrent = _stepCurrent;
    nDXHistoryLogProdIdentMaintainContract.stepMax = _stepMax;
    return nDXHistoryLogProdIdentMaintainContract;
}
